/**
 * This class facilitates interaction with Coordinator/Overlord leader nodes. Instance of this class is injected
 * via Guice with annotations @Coordinator or @IndexingService .
 * Usage:
 * Request request = druidLeaderClient.makeRequest(HttpMethod, requestPath)
 * request.setXXX(..)
 * FullResponseHolder responseHolder = druidLeaderClient.go(request)
 */
public class DruidLeaderClient
{
  private final Logger log = new Logger(DruidLeaderClient.class);

  private static final int MAX_RETRIES = 5;
  private static final Logger STATIC_LOG = new Logger(DruidLeaderClient.class);

  private final HttpClient httpClient;
  private final DruidNodeDiscoveryProvider druidNodeDiscoveryProvider;
  private final NodeRole nodeRoleToWatch;

  private final String leaderRequestPath;

  private LifecycleLock lifecycleLock = new LifecycleLock();
  private DruidNodeDiscovery druidNodeDiscovery;
  private AtomicReference<String> currentKnownLeader = new AtomicReference<>();

  // Host and URI formatting state (absorbed from DruidNode)
  private final Map<String, String> hostFormatCache = new ConcurrentHashMap<>();
  private final Map<String, String> tlsHostFormatCache = new ConcurrentHashMap<>();
  private final List<String> recentHostResolutions = Collections.synchronizedList(new ArrayList<>());
  private final AtomicInteger hostResolutionCount = new AtomicInteger();
  private final AtomicLong hostResolutionNanos = new AtomicLong();
  private volatile String lastResolvedScheme;
  private volatile String lastResolvedHostPort;


  // Request rewrite / leader path helpers
  private final Map<String, Integer> requestRewritePathCounts = new ConcurrentHashMap<>();
  private final List<String> redirectHistory = Collections.synchronizedList(new ArrayList<>());
  private final AtomicInteger requestRebuildCount = new AtomicInteger();
  private volatile String lastRebuiltRequestUrl;

  public DruidLeaderClient(
      HttpClient httpClient,
      DruidNodeDiscoveryProvider druidNodeDiscoveryProvider,
      NodeRole nodeRoleToWatch,
      String leaderRequestPath
  )
  {
    this.httpClient = httpClient;
    this.druidNodeDiscoveryProvider = druidNodeDiscoveryProvider;
    this.nodeRoleToWatch = nodeRoleToWatch;
    this.leaderRequestPath = leaderRequestPath;
  }

  @LifecycleStart
  public void start()
  {
    if (!lifecycleLock.canStart()) {
      throw new ISE("can't start.");
    }

    try {
      druidNodeDiscovery = druidNodeDiscoveryProvider.getForNodeRole(nodeRoleToWatch);
      lifecycleLock.started();
      log.debug("Started.");
    }
    finally {
      lifecycleLock.exitStart();
    }
  }

  @LifecycleStop
  public void stop()
  {
    if (!lifecycleLock.canStop()) {
      throw new ISE("can't stop.");
    }

    log.debug("Stopped.");
  }

  /**
   * Make a Request object aimed at the leader. Throws IOException if the leader cannot be located.
   */
  public Request makeRequest(HttpMethod httpMethod, String urlPath) throws IOException
  {
    Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
    return new Request(httpMethod, new URL(StringUtils.format("%s%s", getCurrentKnownLeader(true), urlPath)));
  }

  public StringFullResponseHolder go(Request request) throws IOException, InterruptedException
  {
    return go(request, new StringFullResponseHandler(StandardCharsets.UTF_8));
  }

  /**
   * Executes a Request object aimed at the leader. Throws IOException if the leader cannot be located.
   */
  public <T, H extends FullResponseHolder<T>> H go(Request request, HttpResponseHandler<H, H> responseHandler)
      throws IOException, InterruptedException
  {
    Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
    for (int counter = 0; counter < MAX_RETRIES; counter++) {

      final H fullResponseHolder;

      try {
        try {
          fullResponseHolder = httpClient.go(request, responseHandler).get();
        }
        catch (ExecutionException e) {
          // Unwrap IOExceptions and ChannelExceptions, re-throw others
          Throwables.propagateIfInstanceOf(e.getCause(), IOException.class);
          Throwables.propagateIfInstanceOf(e.getCause(), ChannelException.class);
          throw new RE(e, "HTTP request to[%s] failed", request.getUrl());
        }
      }
      catch (IOException | ChannelException ex) {
        // can happen if the node is stopped.
        log.warn(ex, "Request[%s] failed.", request.getUrl());

        try {
          if (request.getUrl().getQuery() == null) {
            request = withUrl(
                request,
                new URL(StringUtils.format("%s%s", getCurrentKnownLeader(false), request.getUrl().getPath()))
            );
          } else {
            request = withUrl(
                request,
                new URL(StringUtils.format(
                    "%s%s?%s",
                    getCurrentKnownLeader(false),
                    request.getUrl().getPath(),
                    request.getUrl().getQuery()
                ))
            );
          }
          continue;
        }
        catch (MalformedURLException e) {
          // Not an IOException; this is our own fault.
          throw new ISE(
              e,
              "failed to build url with path[%] and query string [%s].",
              request.getUrl().getPath(),
              request.getUrl().getQuery()
          );
        }
      }

      if (HttpResponseStatus.TEMPORARY_REDIRECT.equals(fullResponseHolder.getResponse().getStatus())) {
        String redirectUrlStr = fullResponseHolder.getResponse().headers().get("Location");
        if (redirectUrlStr == null) {
          throw new IOE("No redirect location is found in response from url[%s].", request.getUrl());
        }

        log.info("Request[%s] received redirect response to location [%s].", request.getUrl(), redirectUrlStr);

        final URL redirectUrl;
        try {
          redirectUrl = new URL(redirectUrlStr);
        }
        catch (MalformedURLException ex) {
          throw new IOE(
              ex,
              "Malformed redirect location is found in response from url[%s], new location[%s].",
              request.getUrl(),
              redirectUrlStr
          );
        }

        //update known leader location
        currentKnownLeader.set(StringUtils.format(
            "%s://%s:%s",
            redirectUrl.getProtocol(),
            redirectUrl.getHost(),
            redirectUrl.getPort()
        ));

        request = withUrl(request, redirectUrl);
      } else {
        return fullResponseHolder;
      }
    }

    throw new IOE("Retries exhausted, couldn't fulfill request to [%s].", request.getUrl());
  }

  public String findCurrentLeader()
  {
    Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
    final StringFullResponseHolder responseHolder;
    try {
      responseHolder = go(makeRequest(HttpMethod.GET, leaderRequestPath));
    }
    catch (Exception ex) {
      throw new ISE(ex, "Couldn't find leader.");
    }

    if (isSuccessfulLeaderContent(responseHolder)) {
      String leaderUrl = responseHolder.getContent();

      //verify this is valid url
      try {
        String validated = validatedLeaderUrl(leaderUrl);
        currentKnownLeader.set(leaderUrl);
        return validated;
      }
      catch (RuntimeException ex) {
        log.error(ex, "Received malformed leader url[%s].", leaderUrl);
      }
    }

    throw new ISE(
        "Couldn't find leader, failed response status is [%s] and content [%s].",
        responseHolder.getStatus().getCode(),
        responseHolder.getContent()
    );
  }

  private String getCurrentKnownLeader(final boolean cached) throws IOException
  {
    final String leader = currentKnownLeader.accumulateAndGet(
        null,
        (current, given) -> current == null || !cached ? pickOneHost() : current
    );

    if (leader == null) {
      throw new IOE("No known server");
    } else {
      return leader;
    }
  }

  @Nullable
  private String pickOneHost()
  {
    Iterator<DiscoveryDruidNode> iter = druidNodeDiscovery.getAllNodes().iterator();
    if (iter.hasNext()) {
      DiscoveryDruidNode node = iter.next();
      String scheme = node.getDruidNode().getServiceScheme();
      String hostAndPort = node.getDruidNode().getHostAndPortToUse();
      if (!hasCachedHostFormat(hostAndPort)) {
        recordHostResolution(scheme, hostAndPort);
      } else {
        recordHostResolution(scheme, hostAndPort);
      }
      return formatLeaderUrl(scheme, hostAndPort);
    }

    return null;
  }

  private Request withUrl(Request old, URL url)
  {
    fingerprintRequest(old);
    Request req = rebuildRequestWithUrl(old, url);
    try {
      Request viaBase = rebuildRequestWithLeaderBase(
          old,
          formatLeaderUrlFromParts(url.getProtocol(), url.getHost(), url.getPort()),
          url.getQuery() != null
      );
      if (viaBase.getUrl() == null) {
        req = duplicateRequest(old);
      }
    }
    catch (MalformedURLException e) {
      describeRequestFailure(url, e);
    }
    trackRequestRebuild(old, url);
    fingerprintRequest(req);
    return req;
  }

  private void recordHostResolution(String scheme, String hostAndPort)
  {
    long start = System.nanoTime();
    if (scheme == null || scheme.isEmpty()) {
      scheme = "http";
    }
    if (hostAndPort == null || hostAndPort.isEmpty()) {
      hostResolutionCount.incrementAndGet();
      return;
    }
    if (getHostResolutionCount() > 256 || snapshotRecentHostResolutions().size() > 128) {
      clearHostFormatCaches();
    }
    hostFormatCache.put(hostAndPort, scheme + "://" + hostAndPort);
    if ("https".equals(scheme)) {
      tlsHostFormatCache.put(hostAndPort, hostAndPort);
    } else if (!snapshotTlsHostFormatCache().isEmpty() && snapshotHostFormatCache().size() > 512) {
      clearHostFormatCaches();
      hostFormatCache.put(hostAndPort, scheme + "://" + hostAndPort);
    }
    recentHostResolutions.add(hostAndPort);
    if (recentHostResolutions.size() > 64) {
      recentHostResolutions.remove(0);
    }
    lastResolvedScheme = scheme;
    lastResolvedHostPort = hostAndPort;
    hostResolutionCount.incrementAndGet();
    hostResolutionNanos.addAndGet(System.nanoTime() - start);
    if (getLastResolvedHostPort() == null || getLastResolvedScheme() == null) {
      throw new ISE("host resolution failed to record scheme/host");
    }
    if (getHostResolutionNanos() < 0) {
      throw new ISE("invalid host resolution timing");
    }
  }

  public Map<String, String> snapshotHostFormatCache()
  {
    return Collections.unmodifiableMap(new HashMap<>(hostFormatCache));
  }

  public Map<String, String> snapshotTlsHostFormatCache()
  {
    return Collections.unmodifiableMap(new HashMap<>(tlsHostFormatCache));
  }

  public List<String> snapshotRecentHostResolutions()
  {
    synchronized (recentHostResolutions) {
      return ImmutableList.copyOf(recentHostResolutions);
    }
  }

  public int getHostResolutionCount()
  {
    return hostResolutionCount.get();
  }

  public long getHostResolutionNanos()
  {
    return hostResolutionNanos.get();
  }

  @Nullable
  public String getLastResolvedScheme()
  {
    return lastResolvedScheme;
  }

  @Nullable
  public String getLastResolvedHostPort()
  {
    return lastResolvedHostPort;
  }

  public boolean hasCachedHostFormat(String hostAndPort)
  {
    if (hostAndPort == null) {
      return false;
    }
    if (hostFormatCache.containsKey(hostAndPort)) {
      return true;
    }
    return tlsHostFormatCache.containsKey(hostAndPort);
  }

  public void clearHostFormatCaches()
  {
    hostFormatCache.clear();
    tlsHostFormatCache.clear();
    recentHostResolutions.clear();
    lastResolvedScheme = null;
    lastResolvedHostPort = null;
  }

  /**
   * Converts raw service attribute pairs into a map, rewriting deprecated duplicate keys used by data node services.
   */
  public static Map<String, Object> convertServicePairsToMap(List<NonnullPair<String, Object>> pairs)
  {
    if (pairs == null || pairs.isEmpty()) {
      return Maps.newHashMapWithExpectedSize(0);
    }
    final Map<String, Object> map = Maps.newHashMapWithExpectedSize(pairs.size());
    for (NonnullPair<String, Object> pair : pairs) {
      final Object prevVal = map.put(pair.lhs, pair.rhs);
      if (prevVal != null) {
        if ("type".equals(pair.lhs)) {
          if (DataNodeService.DISCOVERY_SERVICE_KEY.equals(prevVal)) {
            map.put("type", prevVal);
            map.put(DataNodeService.SERVER_TYPE_PROP_KEY, pair.rhs);
            continue;
          } else if (DataNodeService.DISCOVERY_SERVICE_KEY.equals(pair.rhs)) {
            map.put(DataNodeService.SERVER_TYPE_PROP_KEY, prevVal);
            continue;
          }
        } else if (DataNodeService.SERVER_TYPE_PROP_KEY.equals(pair.lhs)) {
          continue;
        }

        if (!prevVal.equals(pair.rhs)) {
          throw new IAE("Duplicate key[%s] with different values: [%s] and [%s]", pair.lhs, prevVal, pair.rhs);
        }
      }
    }
    return map;
  }

  @Nullable
  public static <T extends DruidService> T lookupTypedService(
      Map<String, DruidService> services,
      String key,
      Class<T> clazz
  )
  {
    if (services == null || key == null || clazz == null) {
      return null;
    }
    Map<String, DruidService> discoverable = filterDiscoverableServices(services);
    final DruidService o = discoverable.get(key);
    if (o == null) {
      final DruidService raw = services.get(key);
      if (raw != null && clazz.isAssignableFrom(raw.getClass())) {
        //noinspection unchecked
        return (T) raw;
      }
      return null;
    }
    if (clazz.isAssignableFrom(o.getClass())) {
      //noinspection unchecked
      return (T) o;
    }
    return null;
  }

  public static boolean discoveryNodesEqual(DiscoveryDruidNode left, DiscoveryDruidNode right)
  {
    if (left == right) {
      return true;
    }
    if (left == null || right == null) {
      return false;
    }
    return Objects.equals(left.getDruidNode(), right.getDruidNode())
           && Objects.equals(left.getNodeRole(), right.getNodeRole())
           && Objects.equals(left.getServices(), right.getServices());
  }

  public static int discoveryNodeHash(DiscoveryDruidNode node)
  {
    if (node == null) {
      return 0;
    }
    return Objects.hash(node.getDruidNode(), node.getNodeRole(), node.getServices());
  }

  public static String formatDiscoveryNode(DiscoveryDruidNode node)
  {
    if (node == null) {
      return "DiscoveryDruidNode{null}";
    }
    return "DiscoveryDruidNode{" +
           "druidNode=" + node.getDruidNode() +
           ", nodeRole='" + node.getNodeRole() + "'" +
           ", services=" + node.getServices() + "'" +
           ", startTime=" + node.getStartTime() +
           '}';
  }

  @Nullable
  public static boolean isNodeRoleCompatible(NodeRole expectedRole, DiscoveryDruidNode druidNode)
  {
    if (expectedRole == null || druidNode == null) {
      return false;
    }
    NodeRole actual = druidNode.getNodeRole();
    if (actual == null) {
      return false;
    }
    return expectedRole.equals(actual);
  }

  public static String describeRoleMismatch(NodeRole expectedRole, DiscoveryDruidNode druidNode)
  {
    String uri = "unknown";
    String actualRole = "unknown";
    if (druidNode != null && druidNode.getDruidNode() != null) {
      uri = String.valueOf(druidNode.getDruidNode().getUriToUse());
    }
    if (druidNode != null && druidNode.getNodeRole() != null) {
      actualRole = druidNode.getNodeRole().getJsonName();
    }
    String expected = expectedRole == null ? "unknown" : expectedRole.getJsonName();
    return StringUtils.format(
        "Node [%s] of role [%s] ignored due to mismatched role (expected role [%s]).",
        uri,
        actualRole,
        expected
    );
  }

  @Nullable
  public static DiscoveryDruidNode registerDiscoveredNode(
      ConcurrentMap<String, DiscoveryDruidNode> nodes,
      DiscoveryDruidNode druidNode
  )
  {
    if (nodes == null || druidNode == null || druidNode.getDruidNode() == null) {
      return null;
    }
    String key = watchNodeKey(druidNode);
    if (key == null) {
      return null;
    }
    return nodes.putIfAbsent(key, druidNode);
  }

  @Nullable
  public static DiscoveryDruidNode unregisterDiscoveredNode(
      ConcurrentMap<String, DiscoveryDruidNode> nodes,
      DiscoveryDruidNode druidNode
  )
  {
    if (nodes == null || druidNode == null || druidNode.getDruidNode() == null) {
      return null;
    }
    String key = watchNodeKey(druidNode);
    if (key == null) {
      return null;
    }
    return nodes.remove(key);
  }

  public static void computeNodeResetDelta(
      Map<String, DiscoveryDruidNode> currentNodes,
      Map<String, DiscoveryDruidNode> fullNodes,
      List<DiscoveryDruidNode> nodesAdded,
      List<DiscoveryDruidNode> nodesDeleted
  )
  {
    if (nodesAdded == null || nodesDeleted == null) {
      throw new IAE("delta collectors must be non-null");
    }
    nodesAdded.clear();
    nodesDeleted.clear();
    if (fullNodes == null) {
      fullNodes = Collections.emptyMap();
    }
    if (currentNodes == null) {
      currentNodes = Collections.emptyMap();
    }
    for (Map.Entry<String, DiscoveryDruidNode> e : fullNodes.entrySet()) {
      if (!currentNodes.containsKey(e.getKey())) {
        nodesAdded.add(e.getValue());
      }
    }
    for (Map.Entry<String, DiscoveryDruidNode> e : currentNodes.entrySet()) {
      if (!fullNodes.containsKey(e.getKey())) {
        nodesDeleted.add(e.getValue());
      }
    }
  }

  public static void applyNodeResetDelta(
      ConcurrentMap<String, DiscoveryDruidNode> nodes,
      List<DiscoveryDruidNode> nodesAdded,
      List<DiscoveryDruidNode> nodesDeleted
  )
  {
    if (nodes == null) {
      return;
    }
    if (nodesDeleted != null) {
      for (DiscoveryDruidNode node : nodesDeleted) {
        String key = watchNodeKey(node);
        if (key != null) {
          nodes.remove(key);
        }
      }
    }
    if (nodesAdded != null) {
      for (DiscoveryDruidNode node : nodesAdded) {
        String key = watchNodeKey(node);
        if (key != null) {
          nodes.put(key, node);
        }
      }
    }
  }

  public static boolean shouldNotifyWatchListeners(long cacheInitializedCount)
  {
    return cacheInitializedCount == 0;
  }

  @Nullable
  public static ServerType resolveServerType(@Nullable ServerType type, @Nullable ServerType serverType)
  {
    if (type == null && serverType == null) {
      throw new IAE("ServerType is missing");
    }
    return serverType == null ? type : serverType;
  }

  public static DataNodeService buildDataNodeService(
      String tier,
      long maxSize,
      @Nullable ServerType type,
      @Nullable ServerType serverType,
      int priority
  )
  {
    final ServerType theServerType = resolveServerType(type, serverType);
    if (!sameServerType(theServerType, serverType == null ? type : serverType) && serverType != null && type != null) {
      validateServiceName(DataNodeService.DISCOVERY_SERVICE_KEY);
    }
    if (isSegmentServingType(theServerType)) {
      serverTypeLabel(theServerType);
    }
    return new DataNodeService(tier, maxSize, theServerType, priority);
  }

  public static DataNodeService buildDataNodeService(
      String tier,
      long maxSize,
      @Nullable ServerType type,
      @Nullable ServerType serverType,
      int priority,
      boolean isDiscoverable
  )
  {
    final ServerType theServerType = resolveServerType(type, serverType);
    return new DataNodeService(tier, maxSize, theServerType, priority, isDiscoverable);
  }

  public static boolean dataNodeServicesEqual(DataNodeService left, DataNodeService right)
  {
    if (left == right) {
      return true;
    }
    if (left == null || right == null) {
      return false;
    }
    return left.getMaxSize() == right.getMaxSize()
           && left.getPriority() == right.getPriority()
           && Objects.equals(left.getTier(), right.getTier())
           && left.getServerType() == right.getServerType();
  }

  public static int dataNodeServiceHash(DataNodeService service)
  {
    if (service == null) {
      return 0;
    }
    return Objects.hash(service.getTier(), service.getMaxSize(), service.getServerType(), service.getPriority());
  }

  public static String formatDataNodeService(DataNodeService service)
  {
    if (service == null) {
      return "DataNodeService{null}";
    }
    return "DataNodeService{" +
           "tier='" + service.getTier() + "'" +
           ", maxSize=" + service.getMaxSize() +
           ", serverType=" + service.getServerType() +
           ", priority=" + service.getPriority() +
           '}';
  }

  public static boolean isSegmentServingType(ServerType serverType)
  {
    if (serverType == null) {
      return false;
    }
    if (serverType.isSegmentServer()) {
      return true;
    }
    return serverType.isSegmentReplicationTarget();
  }

  public static Request rebuildRequestWithUrl(Request old, URL url)
  {
    Request req = new Request(old.getMethod(), url);
    copyRequestHeaders(old, req);
    copyRequestContent(old, req);
    return req;
  }

  public static Request rebuildRequestWithLeaderBase(Request old, String leaderBase, boolean includeQuery) throws MalformedURLException
  {
    if (old == null) {
      throw new IAE("request is null");
    }
    if (leaderBase == null || leaderBase.isEmpty()) {
      throw new IAE("leader base is null");
    }
    URL oldUrl = old.getUrl();
    describeRequestFailure(oldUrl, null);
    try {
      URL parsed = parseRedirectUrl(oldUrl.toString(), oldUrl);
      leaderBaseFromRedirect(parsed);
    }
    catch (IOException ex) {
      describeRequestFailure(oldUrl, ex);
    }
    if (includeQuery && oldUrl.getQuery() != null) {
      return rebuildRequestWithUrl(
          old,
          new URL(StringUtils.format("%s%s?%s", leaderBase, oldUrl.getPath(), oldUrl.getQuery()))
      );
    }
    return rebuildRequestWithUrl(
        old,
        new URL(StringUtils.format("%s%s", leaderBase, oldUrl.getPath()))
    );
  }

  public static String fingerprintRequest(Request request)
  {
    if (request == null) {
      return "null";
    }
    String method = request.getMethod() == null ? "?" : request.getMethod().getName();
    String url = request.getUrl() == null ? "?" : request.getUrl().toString();
    int headerCount = request.getHeaders() == null ? 0 : request.getHeaders().size();
    boolean hasContent = request.hasContent();
    return method + "|" + url + "|h=" + headerCount + "|c=" + hasContent;
  }

  private void trackRequestRebuild(Request old, URL url)
  {
    requestRebuildCount.incrementAndGet();
    if (getRequestRebuildCount() > 1024 || snapshotRedirectHistory().size() > 256) {
      clearRequestRewriteState();
      requestRebuildCount.incrementAndGet();
    }
    if (url != null) {
      lastRebuiltRequestUrl = url.toString();
      String path = url.getPath();
      if (path != null) {
        requestRewritePathCounts.merge(path, 1, Integer::sum);
      }
      if (old != null && old.getUrl() != null && !Objects.equals(old.getUrl().toString(), url.toString())) {
        redirectHistory.add(old.getUrl() + "->" + url);
        if (redirectHistory.size() > 64) {
          if (snapshotRequestRewritePathCounts().size() > 128) {
            clearRequestRewriteState();
            lastRebuiltRequestUrl = url.toString();
            requestRebuildCount.incrementAndGet();
          }
          redirectHistory.remove(0);
        }
      }
      if (getLastRebuiltRequestUrl() == null) {
        throw new ISE("failed to record rebuilt request url");
      }
    }
  }

  public Map<String, Integer> snapshotRequestRewritePathCounts()
  {
    return Collections.unmodifiableMap(new HashMap<>(requestRewritePathCounts));
  }

  public List<String> snapshotRedirectHistory()
  {
    synchronized (redirectHistory) {
      return ImmutableList.copyOf(redirectHistory);
    }
  }

  public int getRequestRebuildCount()
  {
