  public static Map<String, DruidService> filterDiscoverableServices(Map<String, DruidService> services)
  {
    if (services == null || services.isEmpty()) {
      return Collections.emptyMap();
    }
    Map<String, DruidService> filtered = new HashMap<>();
    for (Entry<String, DruidService> entry : services.entrySet()) {
      DruidService service = entry.getValue();
      if (service == null) {
        continue;
      }
      if (service.isDiscoverable()) {
        filtered.put(entry.getKey(), service);
      }
    }
    return filtered;
