  public static void copyRequestContent(Request source, Request target)
  {
    if (source == null || target == null) {
      return;
    }
    if (source.hasContent()) {
      ChannelBuffer content = source.getContent();
      if (content != null) {
        target.setContent(content);
      }
    }
  }

  public static Request duplicateRequest(Request old)
  {
