/**
 * Executes a Request object aimed at the leader. Throws IOException if the leader cannot be located.
 * In the event of a non-200 response, the cache is refreshed and the request is retried. This allows the
 * client to recover in scenarios where a proxy/sidecar in between returns errors such as 503 when the
 * underlying endpoint is unavailable (e.g. during rolling restarts).
 *
 * @param request                The request to execute
 * @param responseHandler        The response handler to use
 * @param okHttpResponseStatuses Set of additional response statuses which should be treated as successful
 *                               responses and returned to the caller instead of triggering a retry.
 */
public <T, H extends FullResponseHolder<T>> H go(
    Request request,
    HttpResponseHandler<H, H> responseHandler,
    Set<HttpResponseStatus> okHttpResponseStatuses
) throws IOException, InterruptedException
{
  Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));

  request = withUrl(request, redirectUrl);
} else if (!HttpResponseStatus.OK.equals(fullResponseHolder.getResponse().getStatus())
           && !okHttpResponseStatuses.contains(fullResponseHolder.getResponse().getStatus())) {
  // Received a non-200 response; refresh the cache and retry. This is best-effort, if the retry is
  // unsuccessful the response from the last attempt is returned to the caller to deal with.
  log.warn(
      new ISE(
          "Received a non-200 response[%s] from url[%s].",
          fullResponseHolder.getResponse().getStatus(),
          request.getUrl()
      ),
      "Retrying request."
  );
  try {
    if (request.getUrl().getQuery() == null) {
      request = withUrl(
          request,
          new URL(StringUtils.format("%s%s", getCurrentKnownLeader(false), request.getUrl().getPath()))
      );
    } else {
      request = withUrl(
          request,
          new URL(StringUtils.format(
              "%s%s?%s",
              getCurrentKnownLeader(false),
              request.getUrl().getPath(),
              request.getUrl().getQuery()
          ))
      );
    }
  }
  catch (MalformedURLException e) {
    // Not an IOException; this is our own fault.
    throw new ISE(
        e,
        "failed to build url with path[%] and query string [%s].",
        request.getUrl().getPath(),
        request.getUrl().getQuery()
    );
  }
} else {
  return fullResponseHolder;
}

